  /sähkölukitus/i,
  /ovipuhelinjärjestelm[aä]/i,
  /oviautomatiikka/i
];

function collectEvidence(text) {
  if (!text || typeof text !== "string") return [];

  const hits = [];

  for (const re of patterns) {
    const m = text.match(re);
    if (m) hits.push(m[0]);
  }

  return [...new Set(hits)];
}

return items.map(item => {
  const row = item.json;

  const tulevat = row["Tulev. Remontit"] || row["Tulev. remontit"] || row["tulevat_remontit"] || "";
  const taloyhtio = row["Taloyhtiö"] || row["taloyhtio"] || "";
  const yhteenveto = row["Yhteenveto"] || row["yhteenveto"] || "";
  const aiTeksti = row["AI_teksti"] || row["ai_teksti"] || "";
  const remontti = row["remontti"] || "";

  const primaryText = `${tulevat}`;
  const fallbackText = `${taloyhtio}\n${yhteenveto}\n${aiTeksti}\n${remontti}`;

  const primaryEvidence = collectEvidence(primaryText);
  const fallbackEvidence = collectEvidence(fallbackText);

  const evidence = primaryEvidence.length > 0 ? primaryEvidence : fallbackEvidence;
  const relevant = evidence.length > 0;

  return {
    json: {
      ...row,
      relevant,
      match_source:
        primaryEvidence.length > 0
          ? "Tulev. Remontit"
          : (fallbackEvidence.length > 0 ? "Muut kentät" : ""),
      evidence,
      remontti: evidence.join(", ")
    }
  };
});

const { pageHtml, ...listing } = $json || {};
